mapper.select:
SELECT d.ID AS id, d.FLOW_KEY AS workflowKey, d.NAME AS workflowName, d.CATEGORY AS description, d.DRAFT_GRAPH_JSON AS graphJson, COALESCE(( SELECT MAX(dp.VERSION) FROM AST_FLOW_DEPLOYMENT dp WHERE dp.FLOW_DEFINITION_ID = d.ID AND (dp.DELETED = 0 OR dp.DELETED IS NULL) AND (dp.ENV_CODE = d.ENV_CODE OR dp.ENV_CODE IS NULL OR d.ENV_CODE IS NULL) ), 0) AS versionNo, CASE WHEN EXISTS ( SELECT 1 FROM AST_FLOW_DEPLOYMENT dp WHERE dp.FLOW_DEFINITION_ID = d.ID AND (dp.DELETED = 0 OR dp.DELETED IS NULL) AND (dp.ENV_CODE = d.ENV_CODE OR dp.ENV_CODE IS NULL OR d.ENV_CODE IS NULL) ) THEN '已发布' ELSE '未发布' END AS status, d.ENV_CODE AS envCode, d.DELETED AS deleted, d.CREATE_USER AS createUser, d.CREATE_TIME AS createTime, d.UPDATE_USER AS updateUser, d.UPDATE_TIME AS updateTime FROM AST_FLOW_DEFINITION d WHERE (d.DELETED = 0 OR d.DELETED IS NULL)
AND d.FLOW_KEY LIKE CONCAT('%', #{req.workflowKey}, '%')
AND d.NAME LIKE CONCAT('%', #{req.workflowName}, '%')
AND d.CATEGORY = #{req.description}
AND d.ENV_CODE = #{req.envCode}
ORDER BY d.UPDATE_TIME DESC, d.ID DESC
